package com.login.demo.controller.api;
import com.login.demo.model.entity.*; import com.login.demo.service.PersonaService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/personas") public class PersonaApiController { private final PersonaService service; public PersonaApiController(PersonaService service){this.service=service;} @GetMapping public Map<String,Object> listar(){return Map.of("status","ok","data",service.listar());} @PostMapping public ResponseEntity<Persona> crear(@RequestBody Persona persona){return ResponseEntity.status(HttpStatus.CREATED).body(service.guardar(persona));} @GetMapping("/{id}/{tipo}") public ResponseEntity<Persona> buscar(@PathVariable Integer id,@PathVariable Integer tipo){return service.buscar(id,tipo).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}/{tipo}") public ResponseEntity<Void> eliminar(@PathVariable Integer id,@PathVariable Integer tipo){service.eliminar(id,tipo);return ResponseEntity.noContent().build();} }
